Evaluate the JavaScript procedural FPS map generator implementation on a scale of 0-10 points:

**Map Generation Quality (4 points)**: Does it create realistic, playable FPS maps with proper room layouts, corridors, and tactical positions? Are maps varied and interesting rather than random noise?

**Connectivity & Features (3 points)**: Does it properly implement flood-fill to ensure all areas are reachable? Are spawn points and weapon pickups strategically placed?

**Performance & Interface (2 points)**: Does it generate maps efficiently at 60 FPS? Does the "Generate New Map" button work with a clear legend?

**Code Architecture (1 point)**: Is the code well-structured with proper procedural generation algorithms and error handling?

Solution A: ```javascript
function generateFPSMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const size = 500;
    const tiles = 50;
    const tileSize = size / tiles;
    const MAX_ROOMS = 10;
    const ROOM_MIN = 6;
    const ROOM_MAX = 10;
    const WEAPON_COUNT = 6;
    const SPAWN_COUNT = 4;

    const COLORS = {
        wall: '#000000',
        floor: '#404040',
        spawn: '#00FF00',
        weapon: '#FF0000'
    };

    // Utility functions
    function rand(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
    function dist(a, b) { return Math.abs(a.x - b.x) + Math.abs(a.y - b.y); }

    // Create map array
    function createGrid() {
        const grid = new Array(tiles);
        for (let i = 0; i < tiles; i++) {
            grid[i] = new Array(tiles).fill(1); // wall
        }
        return grid;
    }

    // Room object
    class Room {
        constructor(x, y, w, h) {
            this.x = x;
            this.y = y;
            this.w = w;
            this.h = h;
            this.center = {x: Math.floor(x + w / 2), y: Math.floor(y + h / 2)};
        }
        intersect(r) {
            return !(this.x + this.w < r.x || r.x + r.w < this.x ||
                     this.y + this.h < r.y || r.y + r.h < this.y);
        }
    }

    // Generate rooms
    function generateRooms() {
        const rooms = [];
        let attempts = 0;
        while (rooms.length < MAX_ROOMS && attempts < 200) {
            const w = rand(ROOM_MIN, ROOM_MAX);
            const h = rand(ROOM_MIN, ROOM_MAX);
            const x = rand(1, tiles - w - 1);
            const y = rand(1, tiles - h - 1);
            const newRoom = new Room(x, y, w, h);
            let ok = true;
            for (let r of rooms) {
                if (newRoom.intersect(r)) { ok = false; break; }
            }
            if (ok) rooms.push(newRoom);
            attempts++;
        }
        return rooms;
    }

    // Carve rooms into grid
    function carveRooms(grid, rooms) {
        for (let r of rooms) {
            for (let i = r.x; i < r.x + r.w; i++) {
                for (let j = r.y; j < r.y + r.h; j++) {
                    grid[i][j] = 0; // floor
                }
            }
        }
    }

    // Connect rooms with corridors
    function connectRooms(grid, rooms) {
        for (let i = 1; i < rooms.length; i++) {
            const c1 = rooms[i - 1].center;
            const c2 = rooms[i].center;
            if (Math.random() < 0.5) {
                horizontalCorridor(grid, c1.x, c2.x, c1.y);
                verticalCorridor(grid, c1.y, c2.y, c2.x);
            } else {
                verticalCorridor(grid, c1.y, c2.y, c1.x);
                horizontalCorridor(grid, c1.x, c2.x, c2.y);
            }
        }
    }

    function horizontalCorridor(grid, x1, x2, y) {
        for (let x = Math.min(x1, x2); x <= Math.max(x1, x2); x++) grid[x][y] = 0;
    }

    function verticalCorridor(grid, y1, y2, x) {
        for (let y = Math.min(y1, y2); y <= Math.max(y1, y2); y++) grid[x][y] = 0;
    }

    // Flood-fill reachability
    function floodFill(grid, start) {
        const visited = new Array(tiles).fill(0).map(()=>Array(tiles).fill(false));
        const stack = [start];
        while (stack.length) {
            const {x, y} = stack.pop();
            if (x < 0 || x >= tiles || y < 0 || y >= tiles) continue;
            if (visited[x][y] || grid[x][y] !== 0) continue;
            visited[x][y] = true;
            stack.push({x:x+1, y});
            stack.push({x:x-1, y});
            stack.push({x, y:y+1});
            stack.push({x, y:y-1});
        }
        return visited;
    }

    // Place spawn points
    function placeSpawns(grid, rooms) {
        const spawns = [];
        const corners = [
            {x: 1, y: 1},
            {x: tiles-2, y: 1},
            {x: 1, y: tiles-2},
            {x: tiles-2, y: tiles-2}
        ];
        for (let i = 0; i < SPAWN_COUNT; i++) {
            const c = corners[i];
            if (grid[c.x][c.y] === 0) {
                grid[c.x][c.y] = 2; // spawn
                spawns.push(c);
            } else {
                // find nearest floor near corner
                for (let d = 1; d < tiles; d++) {
                    const dirs = [
                        {x: c.x + d, y: c.y},
                        {x: c.x - d, y: c.y},
                        {x: c.x, y: c.y + d},
                        {x: c.x, y: c.y - d}
                    ];
                    for (let p of dirs) {
                        if (p.x >=0 && p.x<tiles && p.y>=0 && p.y<tiles && grid[p.x][p.y]===0) {
                            grid[p.x][p.y]=2;
                            spawns.push(p);
                            break;
                        }
                    }
                    if (spawns.length>i) break;
                }
            }
        }
        return spawns;
    }

    // Place weapons
    function placeWeapons(grid, spawns) {
        const weapons = [];
        let attempts = 0;
        while (weapons.length < WEAPON_COUNT && attempts < 1000) {
            const x = rand(1, tiles-2);
            const y = rand(1, tiles-2);
            if (grid[x][y] !== 0) { attempts++; continue; }
            if (spawns.some(s=>dist(s, {x,y})<5)) { attempts++; continue; }
            grid[x][y] = 3; // weapon
            weapons.push({x,y});
        }
    }

    // Draw map
    function draw(grid) {
        ctx.clearRect(0,0,size,size);
        for (let i=0;i<tiles;i++) {
            for (let j=0;j<tiles;j++) {
                const type=grid[i][j];
                if (type===1) ctx.fillStyle=COLORS.wall;
                else if (type===0) ctx.fillStyle=COLORS.floor;
                else if (type===2) ctx.fillStyle=COLORS.spawn;
                else if (type===3) ctx.fillStyle=COLORS.weapon;
                ctx.fillRect(i*tileSize, j*tileSize, tileSize, tileSize);
            }
        }
    }

    // Legend
    function createLegend() {
        let legend = document.getElementById('legend');
        if (!legend) {
            legend = document.createElement('div');
            legend.id = 'legend';
            legend.style.position = 'absolute';
            legend.style.top = '10px';
            legend.style.left = '10px';
            legend.style.padding = '5px';
            legend.style.backgroundColor = 'rgba(0,0,0,0.5)';
            legend.style.color = '#fff';
            legend.style.fontSize = '12px';
            legend.style.lineHeight = '18px';
            document.body.appendChild(legend);
        }
        legend.innerHTML = `
            <div><span style="display:inline-block;width:12px;height:12px;background:${COLORS.wall}"></span> Wall</div>
            <div><span style="display:inline-block;width:12px;height:12px;background:${COLORS.floor}"></span> Floor</div>
            <div><span style="display:inline-block;width:12px;height:12px;background:${COLORS.spawn}"></span> Spawn</div>
            <div><span style="display:inline-block;width:12px;height:12px;background:${COLORS.weapon}"></span> Weapon</div>
        `;
    }

    // Generate button
    function createButton() {
        let btn = document.getElementById('generateBtn');
        if (!btn) {
            btn = document.createElement('button');
            btn.id = 'generateBtn';
            btn.textContent = 'Generate New Map';
            btn.style.position = 'absolute';
            btn.style.bottom = '10px';
            btn.style.left = '10px';
            btn.style.padding = '5px 10px';
            document.body.appendChild(btn);
            btn.addEventListener('click', () => generateFPSMap(canvasId));
        }
    }

    // Main generation loop
    while (true) {
        const grid = createGrid();
        const rooms = generateRooms();
        carveRooms(grid, rooms);
        connectRooms(grid, rooms);
        const spawns = placeSpawns(grid, rooms);
        placeWeapons(grid, spawns);
        const reachable = floodFill(grid, spawns[0] || {x:1,y:1});
        // Count reachable floor tiles
        let reachableFloor = 0, totalFloor = 0;
        for (let i=0;i<tiles;i++)for(let j=0;j<tiles;j++){
            if(grid[i][j]===0||grid[i][j]===2||grid[i][j]===3){ totalFloor++; if(reachable[i][j]) reachableFloor++; }
        }
        if(reachableFloor===totalFloor) {
            draw(grid);
            createLegend();
            createButton();
            break;
        }
    }
}
```

Solution B: function generateMap(canvasId, w = 500, h = 500) {
  const canvas = document.getElementById(canvasId);
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "black";
  const map = Array.from({ length: h }, () => new Array(w).fill(0));

  const directions = [[0, -1], [0, 1], [-1, 0], [1, 0]];

  function carvePath(x, y, len) {
    let dx = 0;
    let dy = 0;
    for (let i = 1; i < len; i++) {
      const dir = Math.floor(Math.random() * 4);
      [dx, dy] = directions[dir];
      carve(x + dx, y + dy);
      carve(x + i * dx, y + i * dy);
    }
  }

  function carve(x, y) {
    if (x >= 0 && x < w && y >= 0 && y < h && map[y][x] === 0) {
      map[y][x] = 1;
      ctx.fillRect(x, y, 1, 1);
    }
  }

  function floodFill(x, y, target) {
    const stack = [[x, y]];
    while (stack.length > 0) {
      const [xx, yy] = stack.pop();
      map[yy][xx] = target;
      for (const [dx, dy] of directions) {
        const newX = xx + dx;
        const newY = yy + dy;
        if (newX >= 0 && newX < w && newY >= 0 && newY < h && map[newY][newX] === 0) {
          stack.push([newX, newY]);
        }
      }
    }
  }

  function generate() {
    ctx.clearRect(0, 0, w, h);
    for (let i = 0; i < 10; i++) {
      carve(Math.floor(Math.random() * w), Math.floor(Math.random() * h), Math.floor(Math.random() * 20) + 1);
    }
    for (let i = 0; i < 5; i++) {
      floodFill(Math.floor(Math.random() * w), Math.floor(Math.random() * h), 2);
    }
    for (let i = 0; i < 5; i++) {
      floodFill(Math.floor(Math.random() * w), Math.floor(Math.random() * h), 3);
    }
  }

  generate();

  const button = document.createElement("button");
  button.innerHTML = "Generate New Map";
  button.onclick = generate;
  document.body.appendChild(button);
}

